import {state,esc,dateKey} from '../../lib/store.js';
import {categories,taskStatus,rangeStart,mainProgress} from '../../lib/progress/model.js';
import {input,area} from '../pixel/primitives.js';
import {action,box,glyph,cat,meter,categoryBadge,categoryIcon,titleHeader} from './shared.js';
export function questForm(id='',type='DAILY'){const t=state.tasks.find(t=>String(t.id)===String(id))||{questType:type,category:'RESEARCH',status:'TODAY',dueDate:dateKey()},options=(name,label,values,value)=>`<label class="field"><span>${label}</span><select name="${name}">${values.map(([key,text])=>`<option value="${esc(key)}" ${value===key?'selected':''}>${esc(text)}</option>`).join('')}</select></label>`;return `<form data-form="quest" data-id="${esc(id)}" class="quest-form">${input('title','TITLE',t.title||'','text','required maxlength="240"')}<div class="formgrid">${options('category','CATEGORY',categories.map(c=>[c,c]),t.category)}${options('questType','QUEST TYPE',[['MAIN','MAIN / +50 EXP'],['SIDE','SIDE / +20 EXP'],['DAILY','DAILY / +10 EXP']],t.questType)}${input('dueDate','DUE DATE',t.dueDate||'','date')}${input('estimatedMinutes','ESTIMATED MINUTES',t.estimatedMinutes??'','number','min="1" max="1440" step="1"')}${options('status','DESTINATION',[['TODAY','TODAY'],['UPCOMING','UPCOMING'],['SOMEDAY','SOMEDAY']],t.done?t.resumeStatus||'TODAY':t.status)}${options('parentTaskId','LINK TO MAIN QUEST (OPTIONAL)',[['','NONE'],...state.tasks.filter(x=>x.questType==='MAIN'&&String(x.id)!==String(id)).map(x=>[String(x.id),x.title])],String(t.parentTaskId||''))}</div>${area('note','NOTE',t.note||'')}<div class="actions"><button class="mc-button primary" type="submit">SAVE QUEST</button>${action('CANCEL','close')}</div></form>`}
function taskRow(t){return `<div class="quest-row ${t.done?'is-done':''}"><input type="checkbox" aria-label="${t.done?'恢复':'完成'} ${esc(t.title)}" data-change="task" data-id="${esc(t.id)}" ${t.done?'checked':''}>${categoryIcon(t.category)}<div class="quest-name"><button type="button" data-action="quest-edit" data-id="${esc(t.id)}">${esc(t.title)}</button>${t.parentTaskId?'<small>SUB QUEST</small>':''}</div>${categoryBadge(t.category)}<span class="quest-date">${t.dueDate===dateKey()?'Today':esc(t.dueDate?.slice(5)||'—')}</span><span class="quest-duration">${t.estimatedMinutes?esc(t.estimatedMinutes)+' min':'—'}</span><span class="quest-type" title="${t.questType}">${glyph(t.questType==='MAIN'?'star':'flag',16)}</span>${action('···','quest-menu',`data-id="${esc(t.id)}" aria-label="任务菜单 ${esc(t.title)}"`,'tiny')}</div>`}
export function questMenu(id){const t=state.tasks.find(t=>String(t.id)===String(id));if(!t)return '';return `<h3>${esc(t.title)}</h3><p>${categoryBadge(t.category)} · ${esc(t.questType)}</p><p class="pre">${esc(t.note||'没有备注')}</p><p>${esc(t.dueDate||'无截止日期')} / ${t.estimatedMinutes||'—'} min</p><div class="actions">${action('EDIT','quest-edit',`data-id="${esc(t.id)}"`)}${action(t.done?'REOPEN':'COMPLETE','quest-toggle',`data-id="${esc(t.id)}"`)}${!t.done? action('SET MAIN QUEST','quest-main',`data-id="${esc(t.id)}"`):''}${action('DELETE','quest-delete',`data-id="${esc(t.id)}"`,'danger')}</div>`}
function calendar(ui){const ym=ui.missionMonth||dateKey().slice(0,7),[y,m]=ym.split('-').map(Number),offset=(new Date(y,m-1,1).getDay()+6)%7,count=new Date(y,m,0).getDate();return box(`${glyph('calendar',17)} CALENDAR // ${new Date(y,m-1).toLocaleDateString('en-GB',{month:'short',year:'numeric'}).toUpperCase()}`,`<div class="quest-calendar">${['M','T','W','T','F','S','S'].map(d=>`<span>${d}</span>`).join('')}${'<span></span>'.repeat(offset)}${Array.from({length:count},(_,i)=>{const d=ym+'-'+String(i+1).padStart(2,'0'),has=state.tasks.some(t=>t.dueDate===d);return `<button type="button" class="${d===dateKey()?'today':''} ${d===ui.questDate?'selected':''}" data-action="quest-date" data-value="${d}" aria-label="查看 ${d} 任务">${i+1}${has?'<i></i>':''}</button>`}).join('')}</div>${ui.questDate?action('CLEAR DATE FILTER','quest-date','data-value=""','micro'):''}`,`<div>${action('‹','mission-month','data-value="-1" aria-label="上个月"','tiny')}${action('›','mission-month','data-value="1" aria-label="下个月"','tiny')}</div>`)}
function mainQuest(){const main=state.tasks.find(t=>String(t.id)===String(state.mainQuestId)&&!t.done&&t.questType==='MAIN')||state.tasks.find(t=>t.questType==='MAIN'&&!t.done);if(!main)return box(`${glyph('star',17)} MAIN QUEST`,`<p class="mc-empty">NO ACTIVE MAIN QUEST</p>${action('SET MAIN QUEST','quest-new','data-type="MAIN"')}`);const {children,percent}=mainProgress(state,main);return box(`${glyph('star',17)} MAIN QUEST`,`<h3 class="main-quest-title">${esc(main.title)}</h3><div class="mc-progress-line">${meter(percent,'主线子任务完成进度')}<span>${percent}%</span></div>${children.length?children.slice(0,4).map(t=>`<label class="quest-child"><input type="checkbox" data-change="task" data-id="${esc(t.id)}" ${t.done?'checked':''}>${esc(t.title)}</label>`).join(''):'<p class="micro muted">在子任务中选择 LINK TO MAIN QUEST，进度将自动计算。</p>'}`,action('EDIT','quest-edit',`data-id="${esc(main.id)}"`,'tiny'))}
function weekly(){const done=state.tasks.filter(t=>t.done&&t.completedAt&&dateKey(t.completedAt)>=rangeStart('week')&&dateKey(t.completedAt)<=dateKey()),max=Math.max(1,...categories.map(c=>done.filter(t=>t.category===c).length));return box(`${glyph('chart',17)} STATS // THIS WEEK`,categories.map(c=>{const n=done.filter(t=>t.category===c).length;return `<div class="mc-stat-row cat-${c}"><span>${c}</span>${meter(n/max*100,c)}<span>${n}</span></div>`}).join('')+'<p class="micro muted">本周完成任务数量</p>')}
export function mission(ui){const tab=ui.questTab||'TODAY',today=state.tasks.filter(t=>t.dueDate===dateKey()||taskStatus(t)==='TODAY'),done=state.tasks.filter(t=>t.done),list=state.tasks.filter(t=>(ui.questDate?t.dueDate===ui.questDate:taskStatus(t)===tab)&&(!ui.questCategory||t.category===ui.questCategory)).sort((a,b)=>tab==='DONE'?(b.completedAt||'').localeCompare(a.completedAt||''):(a.dueDate||'9999').localeCompare(b.dueDate||'9999')),progress=state.tasks.length?Math.round(done.length/state.tasks.length*100):0;const summary=[['focus','TODAY QUESTS',today.filter(t=>t.done).length+' / '+today.length],['star','MAIN QUESTS',state.tasks.filter(t=>!t.done&&t.questType==='MAIN').length+' ACTIVE'],['mission','SIDE QUESTS',state.tasks.filter(t=>!t.done&&t.questType==='SIDE').length+' ACTIVE'],['chart','TOTAL PROGRESS',progress+'%']];return `${titleHeader('MISSION CONTROL','TASK MANAGEMENT CENTER','PLAN TODAY.<br>A MORE FOCUSED TOMORROW.')}<div class="mission-body"><div class="mission-left"><div class="quest-toolbar"><div class="quest-tabs">${['TODAY','UPCOMING','SOMEDAY','DONE'].map(t=>action(t,'quest-tab',`data-value="${t}" aria-pressed="${tab===t}"`,tab===t?'active':'')).join('')}</div>${action('+ NEW QUEST '+cat(),'quest-new','','primary')}</div><div class="quest-summary">${summary.map(([g,label,value])=>`<div>${glyph(g,26)}<span>${label}<b>${value}</b></span></div>`).join('')}</div><section class="quest-list"><div class="quest-list-head"><h2>${glyph('sun',21)} ${ui.questDate||tab}</h2><span class="micro">${list.length} tasks</span></div><div class="quest-filters">${action('ALL','quest-category','data-value=""',!ui.questCategory?'active':'')}${categories.map(c=>action(c,'quest-category',`data-value="${c}"`,ui.questCategory===c?'active':'')).join('')}</div>${list.map(taskRow).join('')||'<div class="mc-empty">NO QUESTS YET<br><small>为今天写下一个小小的目标。</small></div>'}</section></div><aside class="mission-right">${calendar(ui)}${mainQuest()}${weekly()}${box('RECENTLY COMPLETED',done.filter(t=>t.completedAt).sort((a,b)=>b.completedAt.localeCompare(a.completedAt)).slice(0,4).map(t=>`<button type="button" class="recent-quest" data-action="quest-menu" data-id="${esc(t.id)}"><time>${dateKey(t.completedAt).slice(5)}</time><span>${esc(t.title)}</span><small>${esc(t.category)}</small></button>`).join('')||'<p class="mc-empty">NO COMPLETED QUESTS YET</p>',action('VIEW ALL →','quest-tab','data-value="DONE"','tiny'))}</aside></div>`}
